/**
 * Public surface of the DeepSeek direct provider.
 *
 * Two entry points worth knowing:
 *   - `chat()`           — high-level: one prompt → text, with auto-continuation
 *                          across truncations (multi-turn under the hood).
 *   - `completion()`     — low-level: one HTTP turn, returns whatever the
 *                          server sent. Use this if you want to control
 *                          parent_message_id chaining yourself.
 *
 * Session lifecycle:
 *   - `createSession(token)` once per logical conversation thread.
 *   - Reuse the returned `chat_session_id` across turns to keep DeepSeek's
 *     server-side context.
 *
 * Token management:
 *   - Pass a captured `auth_token` (string) to every call.
 *   - For self-renewal, see `tokenManager.refreshToken()` — it shells out to
 *     `scripts/extract-ai-token.mjs` (Playwright + persistent Chrome profile).
 */
export {
  // Core completion + session
  createSession,
  fetchChallenge,
  solveChallenge,
  completion,
  completionWithRetry,
  chat,
  // File upload (vision / docs)
  uploadFile,
  waitForFile,
  // SSE parser (exported for tests / advanced reuse)
  createParser,
  // Error classes
  DirectError,
  DirectAuthError,
  DirectRateLimitError,
  DirectPowError,
  DirectNetworkError,
  DirectAbortedError,
  DirectTimeoutError,
  DirectProtocolError,
  // Helpers
  redact,
} from "./direct.js";

export type {
  Challenge,
  SessionOpts,
  UploadOpts,
  UploadedFile,
  WaitFileOpts,
  ParserCallbacks,
  ParserState,
  CompletionOpts,
  CompletionResult,
  ChatOpts,
  ChatResult,
} from "./direct.js";

export {
  refreshToken,
  isRefreshing,
  msSinceLastRefresh,
  refreshCount,
  onTokenRefresh,
  getScriptPath,
} from "./tokenManager.js";
